from pathlib import Path
p=Path('f1sim/f1sim/tracks.py');s=p.read_text().replace('import glob\n','import glob\nimport math\n')
s=s.replace('OBSTACLES: Tuple[str, ...] = ("", BARE) + OBSTACLE_FAMILIES','OBSTACLES: Tuple[str, ...] = ("", BARE) + OBSTACLE_FAMILIES\n# Fresh controls choose placement, never a separate rendering/physics category.\nASSET_OBSTACLES = ("", BARE, "edge", "line", "pinch", "hard")\nASSET_LABELS = {"mixed": "모든 에셋 혼합", "cardboard_box": "골판지 상자",\n                "wooden_crate": "나무 상자", "steel_drum": "드럼통",\n                "crate_stack_low": "낮은 상자 더미", "barrier_block": "방호 블록",\n                "marker_post": "표지 기둥"}\n\ndef asset_options():\n    from .props import STYLES\n    return ("mixed",) + tuple(STYLES)\n\ndef asset_obstacle_options(track_id):\n    return ("", BARE) if get(track_id).family == "gym" else ASSET_OBSTACLES\n')
s=s.replace('    raw: str = ""\n','    raw: str = ""\n    asset: str = ""  # empty preserves historical raster scenario interpretation\n    scale: float = 1.0\n',1)
s=s.replace('        return s\n\n    def legacy(self)', '        return s + self.asset_suffix()\n\n    def asset_suffix(self):\n        return f"!assets={self.asset}:{self.scale:g}" if self.asset else ""\n\n    def legacy(self)',1)
s=s.replace('        return s\n\n    def display(self)', '        return s + self.asset_suffix()\n\n    def display(self)',1)
s=s.replace('        return " · ".join(parts)','        if self.asset:\n            parts.append(f"{ASSET_LABELS.get(self.asset, self.asset)} · 크기 {self.scale:g}×")\n        return " · ".join(parts)',1)
s=s.replace('        allowed = self.entry.obstacle_options()','        if self.asset and self.asset not in asset_options():\n            raise TrackError(f"알 수 없는 장애물 에셋: {self.asset}")\n        if not math.isfinite(self.scale) or self.scale <= 0:\n            raise TrackError("장애물 크기는 양수여야 합니다")\n        allowed = asset_obstacle_options(self.track) + ("props",) if self.asset else self.entry.obstacle_options()',1)
s=s.replace('    if is_spec(s):\n        return _parse_spec(s).validate()','    if "!assets=" in s:\n        base, config = s.rsplit("!assets=", 1)\n        try:\n            asset, scale = config.split(":")\n            scale = float(scale)\n        except (ValueError, TypeError) as exc:\n            raise TrackError("에셋 설정 형식은 !assets=<에셋>:<크기> 입니다") from exc\n        if asset not in asset_options() or not math.isfinite(scale) or scale <= 0:\n            raise TrackError("등록된 에셋과 양수 크기를 지정하세요")\n        sc = _parse_spec(base) if is_spec(base) else _parse_legacy(base)\n        if sc.raw:\n            raise TrackError("에셋 설정에는 등록된 트랙이 필요합니다")\n        return replace(sc, asset=asset, scale=scale).validate()\n    if is_spec(s):\n        return _parse_spec(s).validate()',1)
p.write_text(s)
p=Path('f1sim/f1sim/maps.py');s=p.read_text();s=s.replace('    if tracks.is_spec(name):\n', '    if "!assets=" in name:\n        from dataclasses import replace\n        from .asset_obstacles import with_asset_obstacles\n        sc = tracks.parse(name)\n        if sc.obstacle and sc.seed is None:\n            raise ValueError("asset obstacle seed must be resolved before loading")\n        base = replace(sc, obstacle="", seed=None, asset="", scale=1.0, reverse=False, mirror=False)\n        t = with_asset_obstacles(load(base.legacy(), **kw), sc.obstacle, sc.seed or 0,\n                                 asset=sc.asset, scale=sc.scale)\n        if sc.mirror:\n            t = t.mirrored()\n        return t.reversed() if sc.reverse else t\n    if tracks.is_spec(name):\n',1);p.write_text(s)
